using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BDApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B2/",P=A+"Props/B2/";
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DetailMezzanine/";static string O=>R+"/Docs/Review/2026-11-10_B2_DetailMezzanine/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");return s;}
 static Material Store(Material m){string p=E+"Materials/"+m.name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,p);m.enableInstancing=true;AssetDatabase.SaveAssetIfDirty(m);return m;}
 static Material Lamp(string name,Color c,float gain){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",.12f);m.SetFloat("_Smoothness",.35f);m.SetColor("_EmissionColor",c*gain);m.EnableKeyword("_EMISSION");m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;return Store(m);}
 public static object Import(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);Directory.CreateDirectory(O);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).Where(m=>m.name.StartsWith("BCM_")).ToDictionary(m=>"B4O_"+m.name.Substring(4));foreach(string n in new[]{"Pipe","PipeRed"})mats["BM_"+n]=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BM_"+n+".mat");mats["B2M_Plate"]=mats["B4O_Plate"];var lens=Lamp("BD_RedLens",new Color(1,.065f,.018f),2.2f);Lamp("BD_RedTaskLens",new Color(1,.10f,.045f),1.4f);mats["B2M_RedLamp"]=lens;
 int nModels=0;foreach(var p in Directory.GetFiles(E,"BD_*.fbx").Concat(Directory.GetFiles(P,"BD_*.fbx")).Select(x=>x.Replace('\\','/'))){var mi=AssetImporter.GetAtPath(p) as ModelImporter;if(!mi)throw new Exception("Import missing "+p);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();nModels++;}AssetDatabase.SaveAssets();return new{models=nModels,materials=mats.Count};}
 static GameObject Put(string n,string asset,Transform parent){var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!src)throw new Exception("Missing "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=n;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);return g;}
 static GameObject Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static List<Vector3> Points(JToken t)=>t["path"].Select(v=>new Vector3((float)v[0],0,-(float)v[1])).ToList();
 static Vector3 At(List<Vector3> ps,float d){for(int i=1;i<ps.Count;i++){float l=Vector3.Distance(ps[i-1],ps[i]);if(d<=l)return Vector3.Lerp(ps[i-1],ps[i],Mathf.Max(0,d/l));d-=l;}return ps.Last();}
 static Light Fixture(Transform p,string n,Vector3 pos,Quaternion rot,float power,float range){var g=Put(n,E+"BD_IndustrialRedLamp.fbx",p);g.transform.localPosition=pos;g.transform.localRotation=rot;var light=Group("RedBulb",g.transform).AddComponent<Light>();light.transform.localPosition=new Vector3(0,0,.245f);light.type=LightType.Point;light.color=new Color(1,.12f,.055f);light.intensity=power;light.range=range;light.shadows=LightShadows.None;return light;}
 static void Record(Scene s){foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}
 public static object Run(){var s=Check();var roots=s.GetRootGameObjects();var network=roots.Single(g=>g.name=="B2_MachineryNetwork").transform;if(network.Find("B2_DetailPass"))throw new Exception("Already applied; targeted repair required");var added=Group("B2_DetailPass",network).transform;var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var oldlights=roots.Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).ToArray();File.WriteAllText(H+"lights_before.json",JsonConvert.SerializeObject(oldlights.Select(l=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(l).ToString(),l.name,owner=l.transform.parent.name,l.intensity,l.range,color=new[]{l.color.r,l.color.g,l.color.b},position=new[]{l.transform.position.x,l.transform.position.y,l.transform.position.z}}),Formatting.Indented));
 var upper=Group("UpperServiceRoutes",added).transform;int count=0;foreach(var t in plan["tunnels"]){string id=(string)t["id"];var group=Group("B2_"+id+"_CrouchPassage",upper).transform;Put("B2_"+id+"_GratingAndStairs",E+"BD_"+id+"_UpperWalk.fbx",group);var collision=Put("B2_"+id+"_WalkingCollision",E+"BD_"+id+"_Collision.fbx",group);foreach(var f in collision.GetComponentsInChildren<MeshFilter>()){f.GetComponent<MeshRenderer>().enabled=false;f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;}count++;}
 var equipment=Group("EquipmentConnections",added).transform;int addons=0;foreach(var p in plan["addons"]){string model=(string)p["model"];if(p["parent"]!=null){var existing=network.GetComponentsInChildren<Transform>().Single(t=>t.name==(string)p["parent"]);var g=Put(existing.name+"_Connections",P+"BD_"+model+".fbx",equipment);g.transform.position=existing.position;g.transform.rotation=existing.rotation;}else{string id=(string)p["room"];var room=network.Find("B2_"+id+"_Sector");var g=Put("B2_"+id+"_PowerConnections",P+"BD_"+model+".fbx",equipment);g.transform.position=room.position;}addons++;}
 var redm=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/BD_RedTaskLens.mat");int ceiling=0,replaced=0;var lighting=Group("RedIndustrialLighting",added).transform;
 // Every corridor gets visible wall fixtures. Ceiling lights are too low for upper crouch routes.
 var original=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_FullFloor/plan.json"));foreach(var t in original["tunnels"]){string id=((string)t["id"]).Split('-')[1];var hall=network.Find("B2_PipeCorridors/B2_"+id+"_"+(string)t["a"]+"_"+(string)t["b"]);foreach(var c in hall.Cast<Transform>().Where(c=>c.name.Contains("PipeWorkLight")||c.name.Contains("RedMarker")).ToArray())c.gameObject.SetActive(false);var ps=Points(t);float len=0;for(int i=1;i<ps.Count;i++)len+=Vector3.Distance(ps[i-1],ps[i]);int n=Mathf.Max(1,Mathf.CeilToInt((len-4)/5.5f));for(int i=0;i<=n;i++){float d=2+(len-4)*i/n;var pos=At(ps,d);var dir=(At(ps,d+.03f)-At(ps,d-.03f)).normalized;var right=Vector3.Cross(Vector3.up,dir);int side=i%2==0?1:-1;Fixture(lighting,"B2_"+id+"_RedWallFixture_"+i,pos+right*side*2.31f+Vector3.up*1.95f,Quaternion.LookRotation(-right*side),1.35f,6.2f);replaced++;}}
 // Keep manufactured task housings, replace their white diffusers and emitted light together.
 foreach(var l in oldlights){if(!l.gameObject.activeInHierarchy)continue;bool red=l.color.r>l.color.g*2;bool bounce=l.name.Contains("Bounce")||l.transform.parent==null||l.transform.parent.name.Contains("Lighting")&&l.name.Contains("Fill");if(bounce){l.color=new Color(1,.18f,.10f);l.intensity=.35f;continue;}if(red){var owner=l.transform.parent;var newer=Fixture(lighting,owner.name+"_VisibleFixture",Vector3.zero,Quaternion.identity,1.15f,6.0f);newer.transform.parent.position=owner.position+owner.forward*.10f;newer.transform.parent.rotation=owner.rotation;owner.gameObject.SetActive(false);replaced++;}else{l.color=new Color(1,.16f,.085f);l.intensity=Mathf.Min(l.intensity*.55f,3.2f);foreach(var r in l.transform.parent.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>m&&(m.name.Contains("Lamp")||m.name.Contains("Light")||m.name.Contains("Diffuser"))?redm:m).ToArray();}ceiling++;}}
 // Rebuild lighting-dependent data after geometry is verified.
 foreach(var c in roots.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))c.useOcclusionCulling=false;
 Record(s);var result=new{upperRoutes=count,equipmentConnections=addons,redFixtures=replaced,recoloredTaskLights=ceiling};File.WriteAllText(O+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object LightingAudit(){var s=Check();var rows=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Light>()).Select(l=>new{id=GlobalObjectId.GetGlobalObjectIdSlow(l).ToString(),l.name,owner=l.transform.parent?.name,l.intensity,l.range,color=new[]{l.color.r,l.color.g,l.color.b},white=l.color.g>.55f&&l.color.b>.55f}).ToArray();File.WriteAllText(O+"lighting.json",JsonConvert.SerializeObject(rows,Formatting.Indented));return new{active=rows.Length,white=rows.Count(l=>l.white)};}
}
